def populate_existing(apps, schema_editor):
    import re
    import unicodedata

    def normalized(value):
        text = unicodedata.normalize("NFKD", value).casefold()
        text = "".join(char for char in text if not unicodedata.combining(char))
        return re.sub(r"[^\w]+", " ", text, flags=re.UNICODE).strip()

    Locality = apps.get_model("geo", "Locality")
    for row in Locality.objects.select_related("district__region").iterator():
        row.region_id = row.district.region_id if row.district_id else None
        row.normalized_name = normalized(row.name)
        row.search_text = normalized(" ".join([
            row.name, *row.aliases,
            row.district.name if row.district_id else "",
            row.district.region.name if row.district_id else "",
        ]))
        row.save(update_fields=["region", "normalized_name", "search_text"])


